"use strict";(self.webpackChunkgeaflow_website=self.webpackChunkgeaflow_website||[]).push([[7890],{304:(e,n,a)=>{a.d(n,{A:()=>t});const t=a.p+"assets/images/1740386529457-b43e2d49-6000-4acf-862c-314ae4f23dbc-b978a4ee5cb4528562660d57e2a936a3.png"},565:(e,n,a)=>{a.d(n,{A:()=>t});const t=a.p+"assets/images/1740454568183-6d42716b-fc84-41a8-945c-c97b81d61135-4ef6d310ca58e8c379c470ae3062d305.png"},4603:(e,n,a)=>{a.d(n,{A:()=>t});const t=a.p+"assets/images/1739276186744-96d40e95-4e29-48ef-8892-1b7dfa60c726-3192c18b6814cae491be535b9a879901.png"},6039:e=>{e.exports=JSON.parse('{"permalink":"/blog/27","source":"@site/blog/27.md","title":"Stream4Graph: Incremental Computation on Dynamic Graphs","description":"Author: Zhang Qi","date":"2025-03-11T00:00:00.000Z","tags":[],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"Stream4Graph: Incremental Computation on Dynamic Graphs","date":"2025-3-11"},"unlisted":false,"prevItem":{"title":"Graph4Stream: Accelerating Stream Computing with Graph-Based Approaches","permalink":"/blog/31"}}')},6651:(e,n,a)=>{a.r(n),a.d(n,{assets:()=>c,contentTitle:()=>o,default:()=>h,frontMatter:()=>s,metadata:()=>t,toc:()=>l});var t=a(6039),i=a(4848),r=a(8453);const s={title:"Stream4Graph: Incremental Computation on Dynamic Graphs",date:"2025-3-11"},o=void 0,c={authorsImageUrls:[]},l=[{value:"1. Graph Computing",id:"1-graph-computing",level:2},{value:"2. Distributed Graph Computing: Spark GraphX",id:"2-distributed-graph-computing-spark-graphx",level:2},{value:"3. Dynamic Graph Computing: Spark Streaming",id:"3-dynamic-graph-computing-spark-streaming",level:2},{value:"4. Incremental Dynamic Graph Computing: Apache GeaFlow (Incubating)",id:"4-incremental-dynamic-graph-computing-apache-geaflow-incubating",level:2},{value:"5. Apache GeaFlow (Incubating) Architecture Overview",id:"5-apache-geaflow-incubating-architecture-overview",level:2},{value:"6. GeaFlow Performance Testing",id:"6-geaflow-performance-testing",level:2},{value:"7. Summary",id:"7-summary",level:2},{value:"References",id:"references",level:2}];function p(e){const n={a:"a",blockquote:"blockquote",code:"code",font:"font",h2:"h2",img:"img",li:"li",ol:"ol",p:"p",pre:"pre",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Author: Zhang Qi"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"It's well known that when we need to perform correlation analysis on data, we typically use SQL join operations. However, Cartesian product calculations during SQL joins require maintaining a large number of intermediate results, which significantly impacts overall data analysis performance. In contrast, graph-based approaches maintain data correlations, transforming correlation analysis into graph traversal operations and greatly reducing the cost of data analysis."}),"\n",(0,i.jsx)(n.p,{children:"However, with the continuous growth in data scale and increasing demand for real-time processing, efficiently solving real-time computation problems on large-scale graph data has become increasingly urgent. Traditional computing engines such as Spark and Flink are gradually falling short of meeting the growing business demands for graph data processing. Therefore, designing a real-time processing engine tailored for large-scale graph data will bring significant advancements to big data processing technologies."}),"\n",(0,i.jsxs)(n.p,{children:["Stream graph computing engine ",(0,i.jsx)(n.a,{href:"https://github.com/apache/geaflow",children:"Apache GeaFlow (Incubating)"}),", which combines the technical advantages of graph processing and stream processing. It implements incremental computation capabilities on dynamic graphs, enhancing real-time performance in high-performance correlation analysis. In the following sections, we will introduce the characteristics of graph computing technology, how the industry addresses large-scale real-time graph computing challenges, and GeaFlow's performance in dynamic graph computation."]}),"\n",(0,i.jsx)(n.h2,{id:"1-graph-computing",children:"1. Graph Computing"}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.font,{style:{color:"rgb(51, 51, 51)"},children:"A graph is a mathematical structure composed of nodes and edges. Nodes represent various entities such as people, locations, objects, or concepts, while edges represent the relationships between these nodes. For example:"})}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.font,{style:{color:"rgb(51, 51, 51)"},children:"Social media"}),(0,i.jsx)(n.font,{style:{color:"rgb(51, 51, 51)"},children:"\uff1aNodes can represent users, and edges can represent friendships."})]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.font,{style:{color:"rgb(51, 51, 51)"},children:"Web pages"}),(0,i.jsx)(n.font,{style:{color:"rgb(51, 51, 51)"},children:"\uff1aNodes represent web pages, and edges represent hyperlinks."})]}),"\n",(0,i.jsx)(n.li,{children:(0,i.jsx)(n.font,{style:{color:"rgb(51, 51, 51)"},children:"Transportation networks: Nodes represent cities, and edges represent roads or air routes."})}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:a(304).A+"",width:"1160",height:"732"})}),"\n",(0,i.jsx)(n.p,{children:"Graphs inherently represent the connections between nodes, and based on these relationships, we can use nodes and edges to process, analyze, and mine information, helping us understand relationships and patterns in complex systems. The computational activities conducted on graphs are referred to as graph computing. Graph computing has many applications, such as identifying user connections and discovering community structures through social network analysis, calculating web page rankings by analyzing hyperlink relationships, and recommending relevant content and products by building relationship graphs based on user behavior and preferences."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.font,{style:{color:"rgb(51, 51, 51)"}})}),"\n",(0,i.jsx)(n.p,{children:'Let\'s take a simple social network analysis algorithm\u2014Weakly Connected Components (WCC)\u2014as an example. WCC helps us identify "friend circles" or "communities" among users. For instance, on a social platform, a group of users who interact through likes, comments, or follows forms a large weakly connected component, while some users may not be connected to this large component, forming smaller weakly connected components.'}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:a(9067).A+"",width:"1040",height:"824"})}),"\n",(0,i.jsx)(n.p,{children:"If we were to build a WCC algorithm based solely on the small graph above, it would be very simple\u2014we could just construct a basic node-edge structure on a personal PC and perform graph traversal. However, if the graph scale expands to hundreds of billions or even trillions, we would need to use large-scale distributed graph computing engines to handle it."}),"\n",(0,i.jsx)(n.h2,{id:"2-distributed-graph-computing-spark-graphx",children:"2. Distributed Graph Computing: Spark GraphX"}),"\n",(0,i.jsx)(n.p,{children:"Graph processing generally falls into two categories: graph computing engines and graph databases. Graph databases include Neo4j, TigerGraph, etc., while graph computing engines include Spark GraphX, Pregel, etc. In this article, we mainly discuss graph computing engines, using Spark GraphX as an example. Spark GraphX is a component of Apache Spark specifically designed for graph computing and analysis. GraphX combines Spark\u2019s powerful data processing capabilities with the flexibility of graph computing, extending Spark\u2019s core functionality and providing users with a unified API for processing graph data."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.font,{style:{color:"rgb(51, 51, 51)"}})}),"\n",(0,i.jsx)(n.p,{children:"How does Spark GraphX handle graph algorithms? GraphX extends Spark RDD by introducing a directed multigraph where both nodes and edges carry attributes, providing users with a vertex-centric parallel abstraction similar to the Pregel computing model. Users need to provide GraphX with the original graph, initial messages, core computation logic (vprog), message-sending component (sendMsg), and message-merging component (mergeMsg). At the start of the computation, GraphX activates all vertices for initialization. Then, based on the user-provided sendMsg component, it determines which vertices to send messages to. In subsequent iterations, only vertices that receive messages are activated for further computation, repeating the process until no new vertices are activated or the maximum iteration count is reached, finally outputting the results."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.font,{style:{color:"rgb(51, 51, 51)"}})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-scala",children:"  def apply[VD: ClassTag, ED: ClassTag, A: ClassTag]\n     (graph: Graph[VD, ED],\n      initialMsg: A,\n      maxIterations: Int = Int.MaxValue,\n      activeDirection: EdgeDirection = EdgeDirection.Either)\n     (vprog: (VertexId, VD, A) => VD,\n      sendMsg: EdgeTriplet[VD, ED] => Iterator[(VertexId, A)],\n      mergeMsg: (A, A) => A)\n    : Graph[VD, ED]\n{\n  var g = graph.mapVertices((vid, vdata) => vprog(vid, vdata, initialMsg))\n\n  // compute the messages\n  var messages = GraphXUtils.mapReduceTriplets(g, sendMsg, mergeMsg)\n\n  // Loop\n  var prevG: Graph[VD, ED] = null\n    var i = 0\n    while (isActiveMessagesNonEmpty && i < maxIterations) {\n      // Receive the messages and update the vertices.\n      prevG = g\n      g = g.joinVertices(messages)(vprog)\n      graphCheckpointer.update(g)\n\n      // Send new messages, skipping edges where neither side received\n      // a message.\n      messages = GraphXUtils.mapReduceTriplets(\n        g, sendMsg, mergeMsg, Some((oldMessages, activeDirection)))\n    }\n}\n"})}),"\n",(0,i.jsx)(n.p,{children:"In summary, users first need to convert raw tabular data from storage into node-edge data types in GraphX and then let Spark handle the processing. This is for offline processing of static graphs. However, in the real world, both the scale of graph data and the relationships between nodes are constantly changing, especially in the era of big data where changes occur rapidly. How to efficiently and real-time process dynamic graph data is a significant challenge."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:a(565).A+"",width:"1626",height:"440"})}),"\n",(0,i.jsx)(n.h2,{id:"3-dynamic-graph-computing-spark-streaming",children:"3. Dynamic Graph Computing: Spark Streaming"}),"\n",(0,i.jsx)(n.p,{children:"For processing dynamic graphs, a common solution is the Spark Streaming framework, which can consume data from various sources and process it. It extends Spark\u2019s core API to enable high-throughput, fault-tolerant real-time stream data processing."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/314644/1740470405961-05389aa3-1b67-4cdf-9c65-ea28641ef89c.png",alt:""})}),"\n",(0,i.jsx)(n.p,{children:"As shown in the figure above, this is the process of Spark Streaming handling real-time data. First, each Receiver in Spark receives a real-time message stream, parses and segments the messages, and then stores the generated graph data in each Executor. When data accumulates to a certain batch, a full-scale computation is triggered, and the final results are output to the user. This is known as the snapshot-based graph computing approach."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.font,{style:{color:"rgb(64, 64, 64)"}})}),"\n",(0,i.jsx)(n.p,{children:"However, this approach has a significant drawback: it involves redundant computation. For example, if we need to compute once per hour, using Spark would require not only computing the current window\u2019s data but also backtracking all historical data, leading to a large amount of redundant computation. Therefore, we need a graph computing solution that supports incremental computation."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.font,{style:{color:"rgb(64, 64, 64)"}})}),"\n",(0,i.jsx)(n.h2,{id:"4-incremental-dynamic-graph-computing-apache-geaflow-incubating",children:"4. Incremental Dynamic Graph Computing: Apache GeaFlow (Incubating)"}),"\n",(0,i.jsx)(n.p,{children:"We know that in traditional stream computing engines like Flink, the processing model allows the system to handle continuously incoming data events. When processing each event, Flink can evaluate changes and execute computations only on the changed parts. This means that in incremental computing, Flink focuses on the latest incoming data rather than the entire dataset. Inspired by Flink\u2019s incremental computing, we developed the incremental graph computing system Apache GeaFlow (Incubating) (also known as the stream graph computing engine), which effectively supports incremental graph iterative computation."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.font,{style:{color:"rgb(64, 64, 64)"}})}),"\n",(0,i.jsx)(n.p,{children:"How does Apache GeaFlow (Incubating) implement incremental graph computing? First, real-time data is input into GeaFlow through connectors. GeaFlow generates internal node-edge structure data based on the real-time data and inserts this data into the underlying graph. Nodes involved in the real-time data within the current window are activated, triggering graph iterative computation."}),"\n",(0,i.jsx)(n.p,{children:"Using the WCC algorithm as an example, for the connected components algorithm, in a time window, each edge\u2019s src id and tar id vertices are activated. In the first iteration, their id information is sent to neighboring nodes. If a neighboring node receives the message and finds that it needs to update its information, it continues to notify its neighbors; otherwise, its iteration terminates."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/314644/1740471552771-36ee8f06-d58e-4cb7-914d-c44e151575a0.png",alt:""})}),"\n",(0,i.jsx)(n.h2,{id:"5-apache-geaflow-incubating-architecture-overview",children:"5. Apache GeaFlow (Incubating) Architecture Overview"}),"\n",(0,i.jsx)(n.p,{children:"The GeaFlow engine consists of three main parts: DSL, Framework, and State. It also provides users with Stream API, Static Graph API, and Dynamic Graph API. The DSL layer is responsible for parsing and optimizing graph query languages like SQL+ISO/GQL, as well as schema inference. It also supports various Connectors such as Hive, Hudi, Kafka, and ODPS. The Framework layer handles runtime scheduling, fault tolerance, shuffle, and coordination of components. The State layer is responsible for storing underlying graph data and persistence, as well as performance optimizations like indexing and predicate pushdown."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:a(4603).A+"",width:"1496",height:"1002"})}),"\n",(0,i.jsx)(n.h2,{id:"6-geaflow-performance-testing",children:"6. GeaFlow Performance Testing"}),"\n",(0,i.jsxs)(n.p,{children:["To verify GeaFlow\u2019s incremental graph computing performance, we designed the following experiment. A batch of data is input into the computing engine in fixed time windows. We use both Spark and GeaFlow to compute the connected components algorithm on the full graph and compare the computation time. The experiment was conducted on 3 machines with 24 cores and 128G memory each. The dataset used is the public ",(0,i.jsx)(n.a,{href:"https://snap.stanford.edu/data/soc-LiveJournal1.html",children:"soc-Livejournal"})," dataset, and the graph algorithm tested is the Weakly Connected Components (WCC) algorithm. We use 500,000 data entries as a computation window, and each time 500,000 entries are input, a graph computation is triggered."]}),"\n",(0,i.jsx)(n.p,{children:"As a batch processing engine, Spark must perform full computations on both incremental and historical data for each batch window, regardless of the window size. On Spark, we can directly call the built-in WCC algorithm in Spark GraphX for computation."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-scala",children:'object SparkTest {\n\n  def main(args: Array[String]): Unit = {\n\n    val iter_num: Int = args(0).toInt\n    val parallel: Int = args(1).toInt\n\n    val spark = SparkSession.builder.appName("HDFS Data Load").config("spark.default.parallelism", args(1)).getOrCreate\n\n    val sc = new JavaSparkContext(spark.sparkContext)\n    val graph = GraphLoader.edgeListFile(sc, "hdfs://rayagsecurity-42-033147014062:9000/" + args(2), numEdgePartitions = parallel)\n\n    val result = graph.connectedComponents(10)\n    handleResult(result)\n    print("finish")\n\n  }\n\n  def handleResult[VD, ED](graph: Graph[VD, ED]): Unit = {\n    graph.vertices.foreachPartition(_.foreach(tuple => {\n\n    }))\n  }\n}\n'})}),"\n",(0,i.jsx)(n.p,{children:"GeaFlow supports SQL+ISO/GQL graph query languages. We used the graph query language to call GeaFlow\u2019s built-in incremental WCC algorithm for testing. The graph query language code is as follows:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-sql",children:"CREATE TABLE IF NOT EXISTS tables (\n  f1 bigint,\n  f2 bigint\n) WITH (\n  type='file',\n  geaflow.dsl.window.size='16000',\n  geaflow.dsl.column.separator='\\t',\n  test.source.parallel = '32',\n  geaflow.dsl.file.path = 'hdfs://xxxx:9000/com-friendster.ungraph.txt'\n);\n\nCREATE GRAPH modern (\n  Vertex v1 (\n    id int ID\n  ),\n  Edge e1 (\n    srcId int SOURCE ID,\n    targetId int DESTINATION ID\n  )\n) WITH (\n  storeType='memory',\n  shardCount = 256\n);\n\nINSERT INTO modern(v1.id, e1.srcId, e1.targetId)\n(\n  SELECT f1, f1, f2\n  FROM tables\n);\n\nINSERT INTO modern(v1.id)\n(\n  SELECT f2\n  FROM tables\n);\n\nCREATE TABLE IF NOT EXISTS tbl_result (\n  vid bigint,\n  \tcomponent bigint\n) WITH (\n  ignore='true',\n  type ='file'\n);\n\nuse GRAPH modern;\n\nINSERT INTO tbl_result\nCALL inc_wcc(10) YIELD (vid, component)\nRETURN vid, component\n;\n"})}),"\n",(0,i.jsx)(n.p,{children:"The figure below shows the experimental results of the connected components algorithm using both methods. With 500,000 data entries per window, Spark involves a lot of redundant computation because it must backtrack all historical data. GeaFlow, however, only activates the nodes and edges involved in the current window for incremental computation, completing each window's computation within seconds with stable performance. As data volume increases, Spark's computation delay grows proportionally due to the increasing amount of historical data to backtrack. In contrast, GeaFlow\u2019s computation time also slightly increases but remains at the second level."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/314644/1740537488877-eb89b886-7c4c-4c5a-8e27-06356b15afa0.png",alt:""})}),"\n",(0,i.jsx)(n.h2,{id:"7-summary",children:"7. Summary"}),"\n",(0,i.jsx)(n.p,{children:"Traditional graph computing solutions (e.g., Spark GraphX) have redundant computation issues in near real-time scenarios. Inspired by Flink's stream processing model and traditional graph computing, we have proposed a solution that supports incremental graph computing. Overall, GeaFlow has the following advantages:"}),"\n",(0,i.jsxs)(n.ol,{children:["\n",(0,i.jsx)(n.li,{children:"GeaFlow outperforms the Spark Streaming + GraphX solution in incremental real-time computing, especially on large-scale datasets."}),"\n",(0,i.jsx)(n.li,{children:"GeaFlow avoids redundant processing of full data through incremental computation, resulting in higher efficiency and shorter computation time without significant performance degradation."}),"\n",(0,i.jsx)(n.li,{children:"GeaFlow supports SQL+GQL hybrid processing languages, making it more suitable for developing complex graph data processing tasks."}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"The GeaFlow project is fully open-sourced. We have built some of the foundational capabilities of the stream graph engine. In the future, we hope to build a unified lakehouse processing engine for graph data based on GeaFlow to meet diverse big data correlation analysis needs. We are also actively preparing to join the Apache Foundation to enrich the open-source big data ecosystem. Therefore, we warmly welcome those interested in graph technology to join our community."}),"\n",(0,i.jsx)(n.h2,{id:"references",children:"References"}),"\n",(0,i.jsxs)(n.ol,{children:["\n",(0,i.jsxs)(n.li,{children:["Apache GeaFlow (Incubating) Project\uff1a",(0,i.jsx)(n.a,{href:"https://github.com/apache/geaflow",children:"https://github.com/apache/geaflow"})]}),"\n",(0,i.jsxs)(n.li,{children:["soc-Livejournal Dataset\uff1a",(0,i.jsx)(n.a,{href:"https://snap.stanford.edu/data/soc-LiveJournal1.html",children:"https://snap.stanford.edu/data/soc-LiveJournal1.html"})]}),"\n",(0,i.jsxs)(n.li,{children:["Apache GeaFlow (Incubating) Issues\uff1a",(0,i.jsx)(n.a,{href:"https://github.com/apache/geaflow/issues",children:"https://github.com/apache/geaflow/issues"})]}),"\n"]})]})}function h(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(p,{...e})}):p(e)}},8453:(e,n,a)=>{a.d(n,{R:()=>s,x:()=>o});var t=a(6540);const i={},r=t.createContext(i);function s(e){const n=t.useContext(r);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),t.createElement(r.Provider,{value:n},e.children)}},9067:(e,n,a)=>{a.d(n,{A:()=>t});const t=a.p+"assets/images/1740386998582-16f67c8e-ee45-48d2-bb5f-f45ec3956273-5c0e5ad8456b2f2e7800ae509a538e78.png"}}]);